'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key = 'debrio-demo-v1';
let state = Debrio.seed();
let storageFailed = false;
try { const saved = JSON.parse(localStorage.getItem(key)); if (saved?.version === 1 && saved.demoMode && Array.isArray(saved.agenda) && saved.agenda.length) state = saved; } catch { storageFailed = true; }
let ui = { route: location.hash.slice(1) || 'lobby', lobbyRole: 'facilitator', waiting: false, joined: false, edit: 0, venue: 'main', panel: 'activity', person: 0, monitor: null, mic: false, camera: false, captions: false, gallery: false, reviewFilter: 'all', search: '', tab: 'evidence' };
const formDrafts=new Map();
const draftKey=form=>form.id+':'+form.dataset.draftKey;
const paths = {
  cameraoff:'<path d="m3 3 18 18M9 5h4a3 3 0 0 1 3 3v2l6-4v12l-6-4v2M2 5v11a3 3 0 0 0 3 3h8M2 5h3"/>',
  more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',
  micoff:'<path d="m3 3 18 18M9 9v3a3 3 0 0 0 5 2M9 5a3 3 0 0 1 6 0v5M5 10v2a7 7 0 0 0 11 6m3-8v2M12 19v3M8 22h8"/>',
  hangup:'<path d="M3 14a17 17 0 0 1 18 0l-2 5-4-2v-3H9v3l-4 2z"/>',
  home: '<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>', build: '<path d="m4 17-1 4 4-1L20 7l-3-3zM14 7l3 3"/>', run: '<rect x="3" y="5" width="13" height="14" rx="3"/><path d="m16 10 5-3v10l-5-3"/>', review: '<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 9 2 2 5-5M8 16h8"/>', book: '<path d="M3 4h6l3 2 3-2h6v15h-6l-3 2-3-2H3zM12 6v15"/>', people: '<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>', settings: '<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>', arrow: '<path d="M4 12h16m-6-6 6 6-6 6"/>', plus: '<path d="M12 4v16M4 12h16"/>', clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>', check: '<path d="m5 12 4 4L19 6"/>', chevron: '<path d="m9 5 7 7-7 7"/>', down: '<path d="m6 9 6 6 6-6"/>', close: '<path d="m6 6 12 12M6 18 18 6"/>', mic: '<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>', camera: '<rect x="2" y="5" width="14" height="14" rx="3"/><path d="m16 10 6-4v12l-6-4"/>', screen: '<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 22h8M12 17v5m-4-12 4-4 4 4M12 6v8"/>', hand: '<path d="M8 13V5a2 2 0 0 1 4 0v7-9a2 2 0 0 1 4 0v10-7a2 2 0 0 1 4 0v10a7 7 0 0 1-12 5l-5-6a2 2 0 0 1 3-3z"/>', chat: '<path d="M21 4H3v14h5l4 4 4-4h5zM7 9h10M7 13h6"/>', rooms: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>', pin: '<path d="m8 3 8 0-1 6 4 5H5l4-5zM12 14v8"/>', download: '<path d="M12 2v13m-5-5 5 5 5-5M3 16v5h18v-5"/>', volume: '<path d="m3 9 5 0 5-5v16l-5-5H3zM17 8a6 6 0 0 1 0 8M20 4a11 11 0 0 1 0 16"/>', pause: '<path d="M8 5v14M16 5v14"/>', play: '<path d="m8 4 12 8-12 8z"/>', copy: '<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>', help: '<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 1 1 5 2l-2 2v2M12 17v1"/>', moon: '<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12z"/>', exit: '<path d="M9 4H3v16h6M8 12h13m-5-5 5 5-5 5"/>', search: '<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>', leaf: '<path d="M5 20C-1 4 15 1 21 3c1 12-5 19-16 17Zm0 0L16 8"/>'
};
const icon = n => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[n] || paths.book}</svg>`;
const btn = (label, action, cls = '', symbol = '', attrs = '') => `<button class="btn ${cls}" data-action="${action}" ${/^(lobby-(facilitator|participant)|venue-|filter-)/.test(action)?`aria-pressed="${action.startsWith('venue-')?ui.venue===action.slice(6):cls.split(' ').includes('selected')}"`:''} ${attrs}>${symbol ? icon(symbol) : ''}${label}</button>`;
const badge = (label, cls = '') => `<span class="badge ${cls}">${label}</span>`;
const initials = name => name.split(' ').slice(0,2).map(n=>n[0]).join('');
const avatar = (p, size = '') => `<span class="avatar tone-${p.id % 5} ${size}" aria-hidden="true">${initials(p.name)}</span>`;
const person = id => state.participants.find(p=>p.id === id);
const current = () => state.agenda[state.current];
const minutes = () => state.agenda.reduce((n,s)=>n + s.minutes, 0);
const formatTime = seconds => `${String(Math.floor(seconds / 60)).padStart(2,'0')}:${String(seconds % 60).padStart(2,'0')}`;
function save() { try { localStorage.setItem(key, JSON.stringify(state)); storageFailed = false; } catch { storageFailed = true; toast('Browser storage is unavailable. Keep this tab open; changes are only in memory.'); } }
let toastTimer;
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(()=>$('#toast').classList.remove('visible'), 4500); }
function go(route) { ui.monitor = null; if (location.hash === '#' + route) render(); else location.hash = route; }
function heading(kicker, title, subtitle, actions = '') { return `<header class="page-heading"><div><h1 tabindex="-1">${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="actions">${actions}</div></header>`; }
function navLink(route,label,symbol) { return `<a href="#${route==='run'&&!ui.joined?'lobby':route}" aria-label="${label}" class="nav-link ${(ui.route === route || route==='run'&&['lobby','participant'].includes(ui.route)) ? 'active' : ''}" ${(ui.route===route||route==='run'&&['lobby','participant'].includes(ui.route))?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span>${route==='run'&&state.started&&!state.ended?'<span class="live-dot"></span>':''}</a>`; }
function render() {
  const focusedAction = document.activeElement?.dataset.action;
  const focusedId = document.activeElement?.id;
  const selection = [document.activeElement?.selectionStart,document.activeElement?.selectionEnd];
  const openDetails = [...document.querySelectorAll('details[open]')].map(el=>el.className);
  const valid = ['lobby','home','build','run','participant','review','resources','templates','settings'];
  if (!valid.includes(ui.route)) ui.route = 'lobby';
  const participantView=ui.route==='participant'||ui.route==='lobby'&&ui.lobbyRole==='participant';
  document.body.classList.toggle('participant-view',participantView);
  if(!['lobby','run','participant'].includes(ui.route)) LocalMedia.stopAll();
  if(ui.route!=='lobby') LocalMedia.pauseMusic();
  ui.mic=LocalMedia.state.mic;ui.camera=LocalMedia.state.camera;
  document.body.dataset.theme=state.settings.theme||'dark';
  document.title = `Debrio · ${{lobby:'Ready to join',home:'Workspace',build:'Agenda builder',run:'Session room',participant:'Participant preview',review:'Session review',resources:'Resources',templates:'Templates',settings:'Workspace settings'}[ui.route]}`;
  $('#app').innerHTML = `<aside class="sidebar" ${participantView?'hidden':''}><a class="brand" href="#home" aria-label="Debrio workshops">${brandMark()}</a><nav aria-label="Main navigation">${navLink('build','Build','build')}${navLink('run','Run','run')}${navLink('review','Review','review')}</nav><div class="sidebar-bottom"><button class="profile" data-action="profile" aria-label="Workspace settings"><span class="avatar">${esc(initials(state.settings.name))}</span></button>${btn('Reset demo','reset','text')}</div></aside><div class="shell"><header class="topbar"><span class="workspace-label">Workshop</span><div class="topbar-right"><button class="icon-button" data-action="theme" aria-label="Switch theme">${icon((state.settings.theme||'dark')==='dark'?'sun':'moon')}</button><div class="segmented role-switch" role="group" aria-label="Preview role">${btn('Facilitator','lobby-facilitator',!participantView?'selected':'')}${btn('Participant','lobby-participant',participantView?'selected':'')}</div></div></header>${storageFailed?'<div class="storage-warning">Changes are not saving. Browser storage is unavailable.</div>':''}<main id="main" tabindex="-1" class="${ui.route==='run'||ui.route==='participant'?'meeting-main':ui.route==='lobby'?'lobby-main':'page'}">${({lobby,home,build,run:meeting,participant:meeting,review,resources,templates,settings}[ui.route])()}</main></div>`;
  document.querySelectorAll('#app form[data-draft-key]').forEach(form=>{for(const [name,value] of formDrafts.get(draftKey(form))||[]){const field=form.elements.namedItem(name);if(field)field.value=value;}});
  LocalMedia.attach();
  document.querySelectorAll('details').forEach(el=>{el.open=openDetails.includes(el.className);});
  const focusTarget=focusedId?document.getElementById(focusedId):focusedAction?[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusedAction):null;
  focusTarget?.focus({preventScroll:true});
  if(focusTarget && Number.isInteger(selection[0]))focusTarget.setSelectionRange?.(...selection);
}
function brandMark(){return '<svg class="debrio-mark" viewBox="0 0 44 44" aria-hidden="true"><path d="M14 0H30A14 14 0 0 1 44 14V30A14 14 0 0 1 30 44H4A4 4 0 0 1 0 40V14A14 14 0 0 1 14 0Z"/><circle cx="27" cy="27" r="7"/></svg>';}
function home() {
  return `${heading('','Workshops','',btn('New workshop','new','primary','plus'))}<section class="workshop-row"><div>${badge(state.ended?'Ended':state.started?'In progress':'Ready')}<h2>${esc(state.title)}</h2><p>${state.agenda.length} activities · ${minutes()} min · 20 people</p></div><div class="actions">${btn('Edit','goto-build','','build')}${btn(state.ended?'Review':'Open session',state.ended?'goto-review':'enter','primary','arrow')}</div></section><div class="home-tools">${btn('Templates','goto-templates','','rooms')}${btn('Resources','goto-resources','','book')}<a class="btn" href="landing.html">Website</a></div>`;
}
function deviceOptions(kind) {
  const type=kind==='camera'?'videoinput':kind==='mic'?'audioinput':'audiooutput',m=LocalMedia.state;
  const available=kind==='speaker'&&!LocalMedia.outputSelection?[]:m.devices.filter(d=>d.kind===type&&d.deviceId!=='default');
  return '<option value="">System default</option>'+available.map((d,i)=>`<option value="${esc(d.deviceId)}" ${m[kind+'Id']===d.deviceId?'selected':''}>${esc(d.label||('Device '+(i+1)))}</option>`).join('');
}
function localTile(){return `<div class="person-tile local-tile">${LocalMedia.state.camera?'<video data-local-video autoplay muted playsinline aria-label="Your camera preview"></video>':avatar({id:0,name:state.settings.name},'large')}<div><span>You</span>${icon(LocalMedia.state.mic?'mic':'close')}</div></div>`;}
function lobby(){
  const m=LocalMedia.state,host=ui.lobbyRole==='facilitator',waiting=state.participants.filter(p=>!p.admitted).length;
  return `<section class="lobby"><section class="lobby-preview" aria-label="Your preview"><div class="lobby-video">${m.camera?'<video data-local-video autoplay muted playsinline aria-label="Your live camera preview"></video>':`<span class="lobby-initials">${esc(initials(state.settings.name))}</span>`}<span class="lobby-you">You</span><span class="lobby-mic" aria-label="${m.mic?'Microphone on':'Microphone off'}">${m.mic?'<meter data-mic-meter min="0" max="100" value="0" aria-label="Microphone input level"></meter>':icon('micoff')}</span></div><div class="device-dock lobby-controls">${dockButton('mic',m.micPending?'Cancel microphone':m.mic?'Mute microphone':'Unmute microphone',m.mic?'mic':'micoff',m.mic)}${dockButton('camera',m.cameraPending?'Cancel camera':m.camera?'Turn camera off':'Turn camera on',m.camera?'camera':'cameraoff',m.camera)}</div>${m.cameraError?`<p class="device-error" role="alert">${esc(m.cameraError)}</p>`:''}${m.micError?`<p class="device-error" role="alert">${esc(m.micError)}</p>`:''}${m.cameraPending||m.micPending?'<p class="device-hint" role="status">Allow access in your browser, or cancel to continue without devices.</p>':''}</section><section class="lobby-join"><h1>${esc(state.title)}</h1><div class="lobby-present"><div class="avatar-stack">${state.participants.slice(0,5).map(p=>avatar(p)).join('')}</div><span>${host?waiting+' waiting to join':state.participants.filter(p=>p.admitted).length+' people are here'}</span></div><div class="lobby-devices">${[['mic','Microphone','mic'],['camera','Camera','camera'],['speaker','Speaker','volume']].map(([kind,label,symbol])=>`<div class="lobby-device">${icon(symbol)}<select id="${kind}-device" data-device="${kind}" aria-label="${label}">${deviceOptions(kind)}</select>${kind==='speaker'?btn('Test sound','sound-check','sound-check-button'):''}</div>`).join('')}</div>${ui.waiting?`<div class="waiting-status" role="status"><span class="live-dot"></span>Waiting for the facilitator</div>${btn('Cancel request','cancel-wait','lobby-join-btn')}<div class="waiting-tools">${btn(m.music?'Pause music':'Play music','music','text small',m.music?'pause':'play')}${btn('Admit me (demo)','join-now','text small')}</div>`:`${btn(host?'Start session':'Ask to join',host?'join-now':'ask-join','primary lobby-join-btn')}`}${m.audioError?`<p class="device-error" role="alert">${esc(m.audioError)}</p>`:''}</section></section>`;
}
function soundCheck(){const m=LocalMedia.state;return `<div id="sound-check-content"><p>Local device check · nothing is recorded or transmitted.</p><label>Microphone level</label><meter data-mic-meter min="0" max="100" value="0" aria-label="Microphone input level"></meter><div class="actions">${btn(m.mic?'Mute microphone':'Unmute microphone','mic','','mic')}${btn(m.listen?'Stop listening':'Hear myself','listen-self','','',!m.mic?'disabled':'')}${btn(m.speaker?'Playing test…':'Test speakers','speaker-test','','volume',m.speaker?'disabled':'')}</div><p class="field-help">Use headphones for Hear myself.</p>${ui.route==='lobby'?`<div class="lobby-music"><div>${icon('volume')}<span>Lobby music</span>${btn(m.music?'Pause':'Play music','music','small',m.music?'pause':'play')}</div><label for="music-volume">Volume</label><input id="music-volume" type="range" min="0" max="1" step=".05" value="${m.volume}"></div>`:''}${m.audioError?`<p class="device-error">${esc(m.audioError)}</p>`:''}</div>`;}

function build() {
  ui.edit = Math.min(ui.edit,state.agenda.length-1); const s=state.agenda[ui.edit];
  return `${heading('BUILD / WORKSHOP DESIGN','Agenda', '', `${btn('Templates','goto-templates','','rooms')}${btn('Resources','goto-resources','','book')}${btn('Workshop details','details','','settings')}${btn('Preview session','enter','primary','arrow')}`)}<div class="builder-summary"><div><h2>${esc(state.title)}</h2><span>${state.agenda.length} activities <span class="separator">·</span> ${minutes()} minutes <span class="separator">·</span> 20 participants</span></div><span id="activity-save-status" class="badge success" role="status">${[...formDrafts.keys()].some(k=>k.startsWith('stage-form:'))?'Unsaved edits':'Saved on this browser'}</span></div><div class="builder-grid"><section class="agenda-list"><div class="section-heading"><h2>Session agenda</h2>${btn('Add','add-stage','small','plus')}</div>${state.agenda.map((a,i)=>`<button class="agenda-row ${i===ui.edit?'selected':''}" data-action="edit-${i}" aria-pressed="${i===ui.edit}"><span class="agenda-number">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(a.title)}</strong><small>${Debrio.templates[a.kind].name}</small></span><span>${a.minutes}m</span></button>`).join('')}<button class="add-row" data-action="add-stage">${icon('plus')} Add an activity or template</button></section><section class="editor panel"><div class="section-heading"><div><h2>Activity ${ui.edit+1}</h2></div>${badge(Debrio.templates[s.kind].name)}</div><form id="stage-form" data-draft-key="${esc(s.id)}"><label for="stage-title">Activity name</label><input id="stage-title" name="title" value="${esc(s.title)}" maxlength="100" required><div class="field-pair"><div><label for="stage-minutes">Duration (minutes)</label><input id="stage-minutes" name="minutes" type="number" min="1" max="120" value="${s.minutes}" required></div><div><label for="stage-group">Conversation & grouping</label><select id="stage-group" name="grouping">${[['main','Main room'],['individual','Individual response · main room'],['home','Home groups · 5 groups of 4'],['practice','Role practice · 4 trios + 2 groups of 4'],['expert','Expert groups · 4 groups of 5']].map(([v,l])=>`<option value="${v}" ${s.grouping===v?'selected':''}>${l}</option>`).join('')}</select></div></div><label for="stage-instructions">Participant instructions</label><textarea id="stage-instructions" name="instructions" rows="6" maxlength="4000" required>${esc(s.instructions)}</textarea><p class="field-help">These instructions appear beside the conversation when you start this activity.</p><div class="inset"><h3>${icon('people')} Assignment preview</h3><p>${assignmentSummary(s.grouping)}</p><div class="avatar-stack">${state.participants.slice(0,6).map(p=>avatar(p)).join('')}<span>+14</span></div>${btn('See all assignments','assignments','text','arrow')}</div><div class="form-footer"><div>${btn('Move up','move-up','small','',ui.edit===0?'disabled':'')}${btn('Move down','move-down','small','',ui.edit===state.agenda.length-1?'disabled':'')}</div><button class="btn primary" type="submit">${icon('check')} Save activity</button></div></form><div class="editor-bottom">${btn('Remove activity','remove-stage','text danger-text','',state.agenda.length===1?'disabled':'')}<span class="subtle">Changes apply to this local rehearsal.</span></div></section></div>`;
}
function assignmentSummary(g) { return {main:'Main room · everyone',individual:'Main room · private responses',home:'5 home groups · 4 people each',practice:'6 groups · practitioner, counterpart, observers',expert:'4 expert groups · 5 people each'}[g]; }
function templates() {
  return `${heading('BUILD / STARTING POINTS','Templates', 'Choose a format to add to your agenda.')}<div class="template-grid">${Object.entries(Debrio.templates).map(([k,t],i)=>`<article class="template-card"><div class="template-visual visual-${i}"><span class="template-index">0${i+1}</span><div class="protocol-diagram">${t.steps.slice(0,4).map((_,j)=>`<span>${j+1}</span>${j<Math.min(3,t.steps.length-1)?icon('arrow'):''}`).join('')}</div><span>${k==='custom'?'FACILITATOR-LED':'STRUCTURED COLLABORATION'}</span></div><div class="template-body"><h2>${t.name}</h2><p>${t.subtitle}</p><ol>${t.steps.map(s=>`<li>${s[0]} <span>${s[1]}m</span></li>`).join('')}</ol>${btn('Add to agenda',`template-${k}`,'','plus')}</div></article>`).join('')}</div>`;
}
function meeting() {
  const participant=ui.route==='participant',s=current(),assigned=Debrio.assignment(ui.person,s.grouping,state.round),overview=ui.venue==='breakouts'&&!participant&&!ui.monitor;
  const members=(participant?state.participants.filter(p=>Debrio.assignment(p.id,s.grouping,state.round).room===assigned.room):state.participants).filter(p=>p.admitted);
  const title={activity:'Activity',people:'People',resources:'Resources',messages:'Messages',polls:'Polls',rooms:'Breakout rooms'}[ui.panel]||'Activity';
  return `<div class="meeting-heading"><h1>${esc(state.title)}</h1><div class="heading-actions">${!participant?`<button class="people-btn" data-action="panel-people" aria-label="People">${icon('people')}<span>${state.participants.filter(p=>p.admitted).length}</span>${state.participants.some(p=>!p.admitted)?`<span class="people-waiting">${state.participants.filter(p=>!p.admitted).length} waiting</span>`:''}</button>`:''}<div class="segmented room-selector">${btn('Main room','venue-main',ui.venue==='main'?'selected':'')}${btn('Breakout rooms','venue-breakouts',ui.venue==='breakouts'?'selected':'')}</div></div></div>${state.ended?`<div class="session-banner">Session ended. ${btn('Open review','goto-review','text')}</div>`:''}<div class="meeting-grid ${ui.panel?'':'panel-closed'}"><section class="meeting-stage">${overview?roomOverview():`<div class="canvas-top">${btn(ui.gallery?'Presentation view':'Gallery view','gallery','small')}</div>${ui.gallery?gallery():presentation()}<div class="participant-strip">${localTile()}${members.slice(0,7).map(p=>`<div class="person-tile">${avatar(p,'large')}<div><span>${esc(p.name)}</span>${icon('micoff')}</div></div>`).join('')}</div>`}${ui.monitor?`<div class="monitor-banner">${ui.monitor.mode} in ${esc(ui.monitor.room)} · room notified · demo ${btn('Stop','stop-monitor','text')}</div>`:''}${['cameraError','micError'].filter(k=>LocalMedia.state[k]).map(k=>`<p class="device-error" role="alert">${esc(LocalMedia.state[k])}</p>`).join('')}${ui.captions?'<div class="caption-line"><strong>Sample caption:</strong> Start with what you observed.</div>':''}</section>${ui.panel?`<aside class="meeting-panel" aria-label="${title}"><div class="panel-head"><h2>${title}</h2><button class="icon-button" data-action="close-panel" aria-label="Close side panel">${icon('close')}</button></div><div class="panel-content">${sessionPanel(participant)}</div></aside>`:''}</div>${meetingFooter(participant)}`;
}
function meetingFooter(participant){return `<footer class="meeting-footer"><div class="time-meta"></div><div class="device-dock">${dockButton('mic',ui.mic?'Mute microphone':'Unmute microphone',ui.mic?'mic':'micoff',ui.mic)}${dockButton('camera',ui.camera?'Turn camera off':'Turn camera on',ui.camera?'camera':'cameraoff',ui.camera)}<span class="dock-divider"></span>${dockButton('present','Present','screen',false)}${dockButton('hand','Raise hand','hand',false)}${dockButton('session-options','Session options','more',false)}${dockButton(participant?'goto-home':state.ended?'goto-review':'end','Leave session','hangup',false)}</div><div class="tool-dock" role="group" aria-label="Session panels">${[['activity','Activity','book'],['rooms','Rooms','rooms'],['resources','Resources','copy'],['messages','Messages','chat'],['polls','Polls','settings']].map(([k,label,symbol])=>`<button class="tool-button ${ui.panel===k?'on':''}" data-action="panel-${k}" aria-pressed="${ui.panel===k}">${icon(symbol)}<span>${label}</span></button>`).join('')}</div></footer>`;}

function dockButton(action,label,symbol,active) { return `<button class="dock-button ${active?'on':''} ${['mic','camera'].includes(action)&&!active?'off':''} ${symbol==='hangup'?'leave':''}" data-action="${action}" aria-label="${label}" title="${label}" ${['mic','camera','timer'].includes(action)?`aria-pressed="${active}"`:''}>${icon(symbol)}</button>`; }

function presentation(){const s=current();return `<div class="presentation"><div class="slide-content"><h2>${esc(s.title)}</h2><p>${esc(s.instructions)}</p><dl class="slide-brief"><div><dt>Working format</dt><dd>${esc(assignmentSummary(s.grouping))}</dd></div><div><dt>Expected output</dt><dd>${['home','expert'].includes(s.grouping)?'Group response':'Individual response and rationale'}</dd></div></dl></div><div class="slide-footer"><span>Workshop presentation</span><span>Activity ${state.current+1} of ${state.agenda.length}</span></div></div>`;}

function gallery() { return `<div class="gallery">${state.participants.filter(p=>p.admitted).slice(0,9).map(p=>`<div class="gallery-tile tone-${p.id%5}">${avatar(p,'huge')}<span>${esc(p.name)} ${icon('mic')}</span></div>`).join('')}</div>`; }
function roomOverview() {
  const grouping = ['main','individual'].includes(current().grouping)?'home':current().grouping;
  const rooms = [...new Set(state.participants.map(p=>Debrio.assignment(p.id,grouping,state.round).room))];
  return `<div class="section-heading room-heading"><div><h2>Breakout rooms</h2><p>${rooms.length} rooms · ${grouping==='practice'?'Role practice':grouping==='expert'?'Expert groups':'Home groups'}</p></div>${btn('Announce','announce','','volume')}</div><div class="room-grid">${rooms.map((r,i)=>{const members=state.participants.filter(p=>Debrio.assignment(p.id,grouping,state.round).room===r), h=state.help.find(h=>h.room===r&&!h.resolved);return `<article class="room-card ${h?'needs-help':''}"><div class="section-heading"><h3><span class="room-symbol">${String(i+1).padStart(2,'0')}</span>${r}</h3>${badge(h?'Help requested':'In conversation',h?'amber':'success')}</div><div class="avatar-stack">${members.map(p=>avatar(p)).join('')}</div><p>${h?esc(h.text):`${members.length} participants · ${esc(current().title)}`}</p><div class="room-actions">${btn('Listen',`listen-${i}`,'small','volume')}${btn('Speak',`speak-${i}`,'small','mic')}${btn('Join',`join-${i}`,'small','arrow')}</div>${h?btn('Mark help resolved',`resolve-${h.id}`,'text small','check'):''}</article>`;}).join('')}</div>`;
}
function sessionPanel(participant) {
  const s=current(), p=person(ui.person), a=Debrio.assignment(p.id,s.grouping,state.round);
  if(ui.panel==='polls')return pollView(participant);
  if(ui.panel==='rooms')return `<p class="subtle">${assignmentSummary(s.grouping)}</p>${btn('Open breakout rooms','venue-breakouts','full','rooms')}${btn('Return to main room','venue-main','full')}${participant?`<label for="preview-person">Preview participant</label><select id="preview-person">${state.participants.map(p=>`<option value="${p.id}" ${p.id===ui.person?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:btn('Announce','announce','full','volume')}`;
  if(!participant&&ui.panel==='activity')return `<div class="act-timer"><span class="timer" id="timer">${formatTime(Debrio.remaining(state))}</span><div class="act-timer-controls">${dockButton('timer',state.deadline?'Pause timer':'Start timer',state.deadline?'pause':'play',!!state.deadline)}${dockButton('add-minute','Add one minute','plus',false)}</div></div><h2 class="act-title">${esc(s.title)}</h2><p class="act-task">${esc(s.instructions)}</p><div class="act-output">${icon('review')}<span>${['home','expert'].includes(s.grouping)?'Group response':'Individual response and rationale'}</span></div><div class="act-actions">${btn('Next step','next','primary','arrow',state.ended||state.current===state.agenda.length-1?'disabled':'')}${btn('Breakouts','venue-breakouts','','rooms')}</div>${s.grouping==='practice'?`<div class="practice-round">${badge('Round '+(state.round+1))}${btn('Rotate roles','rotate','text','arrow')}</div>`:''}<div class="flow-list">${state.agenda.map((a,i)=>`<button class="flow-step ${i===state.current?'current':''}" data-action="jump-${i}" ${state.ended?'disabled':''}><span>${i<state.current?icon('check'):i+1}</span><span>${esc(a.title)}</span><small>${a.minutes} min</small></button>`).join('')}</div>`;
  if (ui.panel==='people') return `<div class="section-heading"><h2>People</h2>${badge('20 invited')}</div>${!participant&&state.participants.some(p=>!p.admitted)?`<div class="inset"><h3>In the waiting room</h3>${state.participants.filter(p=>!p.admitted).map(p=>`<div class="person-row">${avatar(p)}<span>${esc(p.name)}</span>${btn('Admit',`admit-${p.id}`,'small')}</div>`).join('')}${btn('Admit everyone','admit-all','text','check')}</div>`:''}${state.participants.filter(p=>p.admitted).map(p=>`<div class="person-row">${avatar(p)}<span>${esc(p.name)}<small>${esc(Debrio.assignment(p.id,s.grouping,state.round).room)} · ${esc(Debrio.assignment(p.id,s.grouping,state.round).role)}</small></span></div>`).join('')}`;
  if (ui.panel==='resources') { const items=participant?Debrio.visibleResources(state,p.id):state.resources;return `<div class="section-heading"><h2>Resources</h2>${badge(items.length+' items')}</div><p class="subtle">${participant?'Released materials for your current assignment.':'Release the right context at the right moment.'}</p>${items.map(r=>`<div class="resource-mini">${icon('book')}<div><strong>${esc(r.title)}</strong><small>${esc(r.audience)} · ${r.released?'Released':'Not released'}</small><div class="actions">${btn('Open',`resource-${r.id}`,'text small')}${!participant&&!r.released?btn('Release',`release-${r.id}`,'text small'):''}</div></div></div>`).join('')||empty('Nothing shared yet','Your facilitator will release resources here.')}`; }
  if(ui.panel==='messages') { const room=Debrio.assignment(ui.person,s.grouping,state.round).room;return `<div class="section-heading"><h2>Messages & help</h2>${!participant?btn('Announce','announce','small','volume'):''}</div>${!participant?state.help.filter(h=>!h.resolved).map(h=>`<div class="help-item">${badge('Help · '+esc(h.room),'amber')}<p>${esc(h.text)}</p>${btn('Resolve',`resolve-${h.id}`,'text small','check')}</div>`).join(''):btn('Request help','help','small','hand')}<div class="message-list">${state.messages.filter(m=>!participant||m.target==='all'||m.target===room).map(m=>`<article class="message"><div><strong>${esc(m.author)}</strong><time>${esc(m.time)}</time></div><p>${esc(m.text)}</p><small>${m.target==='all'?'Everyone':esc(m.target)} · saved in demo</small></article>`).join('')}</div><form id="message-form" data-draft-key="${participant?'person-'+ui.person+':'+esc(room):'facilitator'}"><label for="message-text">${participant?'Message your room':'Message everyone'}</label><textarea id="message-text" name="text" rows="3" maxlength="1000" required></textarea><button class="btn primary" type="submit">${icon('arrow')} Send in demo</button></form>`; }
  return `<div class="eyebrow">ACTIVITY ${state.current+1} OF ${state.agenda.length}</div><h2>${esc(s.title)}</h2>${badge(Debrio.templates[s.kind].name)}<p class="activity-instructions">${esc(s.instructions)}</p>${participant?`<div class="inset"><div class="eyebrow">YOUR ASSIGNMENT</div><strong>${esc(a.room)}</strong><p>${esc(a.role)}${s.grouping==='practice'?' · Round '+(state.round+1):''}</p></div><form id="response-form"><label for="response">Your ${s.title.toLowerCase().includes('retry')?'revised attempt':'response'}</label><textarea id="response" name="text" rows="5" maxlength="5000" placeholder="Capture your thinking…" required ${state.ended?'disabled':''}>${esc(state.drafts[p.id+':'+s.id]||'')}</textarea><span class="field-help" id="draft-status">Private to you and the facilitator. Saved as you type.</span><button type="submit" class="btn primary full" ${state.ended?'disabled':''}>${icon('check')} Submit response</button></form>${myAttempts(p.id)}${groupWork(p.id)}${btn('Request help','help','full','hand')}`:`<div class="inset"><h3>${icon('people')} Where people work</h3><p>${assignmentSummary(s.grouping)}</p>${s.grouping==='practice'?`${badge('Round '+(state.round+1))}${btn('Rotate roles','rotate','text','arrow')}`:''}</div><details class="flow-details"><summary>Full agenda</summary><div class="flow-list">${state.agenda.map((a,i)=>`<button class="flow-step ${i===state.current?'current':''}" data-action="jump-${i}" ${state.ended?'disabled':''}><span>${i<state.current?icon('check'):i+1}</span><span>${esc(a.title)}</span><small>${a.minutes}m</small></button>`).join('')}</div></details>${pollView(false)}`}`;
}
function myAttempts(id) { return state.attempts.filter(a=>a.author===id&&!a.group).slice(-2).map(a=>`<article class="attempt-mini"><div class="section-heading"><strong>Attempt ${a.version}</strong>${badge('Submitted','success')}</div><p>${esc(a.text)}</p>${a.feedback?`<blockquote><strong>Facilitator feedback</strong><br>${esc(a.feedback)}</blockquote>`:''}<button class="btn text small" data-action="consent-${a.id}">${icon(a.approved?'check':'plus')}${a.approved?'Withdraw workshop sharing':'Allow this version in workshop debrief'}</button></article>`).join(''); }
function groupWork(id) {
  const s=current(), a=Debrio.assignment(id,s.grouping,state.round);
  if(!['home','expert'].includes(s.grouping))return '';
  const draftKey='group:'+s.id+':'+a.room;
  const submitted=state.attempts.filter(item=>item.group===a.room&&item.stage===s.id).at(-1);
  return `<div class="poll"><div class="eyebrow">${esc(a.room)} · SHARED GROUP WORK</div><h3>Group output</h3><p class="field-help">Everyone in this assigned group can edit. Your recorder submits a snapshot attributed to the whole group. Submitted group work may be shown within this workshop.</p><form id="group-form"><label for="group-response">Group output</label><textarea id="group-response" name="text" data-draft="${esc(draftKey)}" rows="5" maxlength="5000" required ${state.ended?'disabled':''}>${esc(state.drafts[draftKey]||'')}</textarea><p class="field-help">Saved on this browser. Switch preview participants to contribute as another group member.</p><button class="btn primary full" type="submit" ${a.role!=='recorder'||state.ended?'disabled':''}>${icon('check')} ${a.role==='recorder'?'Submit group output':'Your recorder submits this output'}</button></form>${submitted?`<div class="attempt-mini">${badge('Group output submitted · v'+submitted.version,'success')}<p>${esc(submitted.text)}</p></div>`:''}</div>`;
}
function pollView(participant) { const poll=state.poll, votes=Object.values(poll.votes); return `<div class="poll"><div class="eyebrow">AGGREGATE ONLY</div><h3>${esc(poll.question)}</h3>${poll.options.map((o,i)=>`<div class="poll-option">${participant&&poll.open?`<button data-action="vote-${i}" aria-pressed="${poll.votes[ui.person]===i}">${poll.votes[ui.person]===i?icon('check'):''}${esc(o)}</button>`:`<span>${esc(o)}</span>`}${!participant||poll.revealed?`<div class="poll-bar"><span style="width:${votes.length?votes.filter(v=>v===i).length/votes.length*100:0}%"></span></div><small>${votes.filter(v=>v===i).length} responses</small>`:''}</div>`).join('')}<small>${poll.open?'Voting open':'Voting closed'} · ${votes.length} responses${participant&&!poll.revealed?' · Results hidden':''}</small>${!participant?`<div class="actions">${btn(poll.open?'Close voting':'Reopen','poll-toggle','text small')}${btn(poll.revealed?'Hide results':'Reveal results','poll-reveal','text small')}</div>`:''}</div>`; }
function review() {
  let items=state.attempts.filter(a=>(ui.reviewFilter==='all'||ui.reviewFilter==='individual'&&!a.group||ui.reviewFilter==='group'&&a.group||ui.reviewFilter==='pinned'&&a.pinned)&&(!ui.search||`${a.text} ${person(a.author).name} ${a.title}`.toLowerCase().includes(ui.search.toLowerCase())));
  return `${heading('REVIEW / LEARNING EVIDENCE','Review', '',`${btn('Export records','export','', 'download')}${btn('Present debrief','debrief','primary','screen')}`)}<div class="review-summary"><div><strong>${state.attempts.length}</strong><span>submitted attempts</span></div><div><strong>${new Set(state.attempts.filter(a=>!a.group).map(a=>a.author)).size}</strong><span>individual contributors</span></div><div><strong>${state.attempts.filter(a=>a.previous).length}</strong><span>linked revisions</span></div><div><strong>${Debrio.curated(state).length}</strong><span>approved debrief items</span></div></div><div class="review-layout"><section><div class="filterbar"><div class="segmented">${[['all','All work'],['individual','Individual'],['group','Group'],['pinned','Pinned']].map(([k,l])=>btn(l,`filter-${k}`,ui.reviewFilter===k?'selected':'')).join('')}</div><label class="search-field">${icon('search')}<span class="sr-only">Search evidence</span><input id="evidence-search" type="search" placeholder="Search work…" value="${esc(ui.search)}"></label></div><div class="evidence-list">${items.map(a=>`<article class="evidence-card"><div class="evidence-header">${avatar(person(a.author))}<div><h3>${a.group?esc(a.group)+' group':esc(person(a.author).name)}</h3><span>${esc(a.title)} · Version ${a.version}</span></div>${badge(a.previous?'Linked revision':a.group?'Group output':'Individual','neutral')}</div><p class="evidence-text">${esc(a.text)}</p>${a.previous?`<button class="text-link" data-action="compare-${a.id}">${icon('copy')} Compare with previous attempt</button>`:''}${a.feedback?`<div class="feedback-preview"><strong>Feedback</strong><p>${esc(a.feedback)}</p></div>`:''}<div class="evidence-footer"><span class="consent-label">${icon(a.approved?'check':'help')} ${a.approved?'Approved for workshop debrief':'Sharing approval needed'}</span><div class="actions">${btn('Feedback',`feedback-${a.id}`,'small','chat')}${btn(a.pinned?'Pinned':'Pin',`pin-${a.id}`,a.pinned?'small selected':'small','pin')}</div></div></article>`).join('')||empty('No work here yet','Try a different filter, or submit a response in participant preview.')}</div></section><aside class="debrief-sidebar panel"><h2>Debrief</h2><p>Pinned, approved work appears here.</p>${state.attempts.filter(a=>a.pinned).map((a,i)=>`<div class="debrief-item"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${a.group?esc(a.group)+' group':esc(person(a.author).name)}</strong><p>${esc(a.text.slice(0,95))}…</p>${badge(a.approved?'Ready to share':'Waiting for approval',a.approved?'success':'amber')}</div></div>`).join('')||empty('Start with one moment','Pin a piece of work to build your debrief.')}<div class="inset"><h3>A question worth asking</h3><p>“What changed in your thinking, and what helped it change?”</p></div>${btn('Preview debrief','debrief','full primary','screen')}<p class="field-help">Approval is specific to this version and workshop audience. Client sharing is not enabled in this demo.</p></aside></div>`;
}
function resources() { return `${heading('BUILD / RESOURCE LIBRARY','Resources', '',btn('Add resource','add-resource','primary','plus'))}<div class="resource-table panel"><div class="resource-table-head"><span>Resource</span><span>Audience</span><span>Availability</span><span>Actions</span></div>${state.resources.map(r=>`<article class="resource-table-row"><div class="resource-name">${icon('book')}<span><strong>${esc(r.title)}</strong><small>${esc(r.type)} · Version 1</small></span></div><span>${esc(r.audience==='all'?'Everyone':r.audience)}</span><span>${badge(r.released?'Released':'Manual release',r.released?'success':'neutral')}</span><div class="actions">${btn('Open',`resource-${r.id}`,'small')}${btn(r.released?'Unrelease':'Release',`release-${r.id}`,'small')}</div></article>`).join('')}</div><div class="bottom-callout"><div>${icon('help')}<span>Private briefs follow a person’s assigned role. Visiting a room never grants access.</span></div>${btn('Participant view','goto-participant','text','arrow')}</div>`; }
function settings() { return `${heading('WORKSPACE / SETTINGS','Settings', 'Demo preferences are saved only in this browser.')}<div class="settings-grid"><form data-draft-key="settings" id="settings-form" class="panel"><h2>Workspace details</h2><label for="settings-name">Your name</label><input id="settings-name" name="name" value="${esc(state.settings.name)}" required maxlength="70"><label for="settings-workspace">Workspace name</label><input id="settings-workspace" name="workspace" value="${esc(state.settings.workspace)}" required maxlength="70"><button class="btn primary" type="submit">Save preferences</button></form><section class="panel"><h2>Demo</h2><p>This prototype runs locally with fictional people and sample work. No account is required.</p><dl class="settings-facts"><div><dt>Plan</dt><dd>Demo access</dd></div><div><dt>Camera & mic</dt><dd>Local devices</dd></div><div><dt>Data</dt><dd>This browser only</dd></div><div><dt>Payments & email</dt><dd>Not connected</dd></div></dl>${btn('Download demo data','export','','download')}${btn('Reset to sample workshop','reset','text danger-text')}</section></div>`; }
function empty(title,description) { return `<div class="empty-state">${icon('book')}<h3>${title}</h3><p>${description}</p></div>`; }
let dialogTrigger;
function modal(title,content,wide=false) { dialogTrigger=document.activeElement; const d=$('#dialog'); d.classList.toggle('wide-dialog',wide);d.innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${content}`;if(!d.open)d.showModal(); }
function close() { $('#dialog').close(); if(dialogTrigger?.isConnected)dialogTrigger.focus(); }
function confirmAction(title,body,action,label='Confirm') { modal(title,`<p>${body}</p><div class="dialog-actions">${btn('Cancel','close')}${btn(label,action,'primary')}</div>`); }
function roomNames() {const g=['main','individual'].includes(current().grouping)?'home':current().grouping;return [...new Set(state.participants.map(p=>Debrio.assignment(p.id,g,state.round).room))];}
function transition(index) { if(index===state.current)return;const next=state.agenda[index];modal('Start activity?',`<div class="inset"><div class="eyebrow">ACTIVITY ${index+1}</div><h3>${esc(next.title)}</h3><p>${assignmentSummary(next.grouping)}</p><p>${next.minutes} minutes · ${Debrio.templates[next.kind].name}</p></div><p>People will see the new instructions and assignments. Existing drafts and submitted work stay saved.</p><label class="check-label"><input id="transition-confirm" type="checkbox" required> I’ve checked the group is ready, including any unfinished work.</label><div class="dialog-actions">${btn('Keep working','close')}${btn('Start activity',`advance-${index}`,'primary','arrow')}</div>`); }
document.addEventListener('click',async event=>{ const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
  if(action.startsWith('goto-')){close();go(action.slice(5));return;}
  if(action==='close'){close();return;}
  if(action==='enter'){ui.waiting=false;go('lobby');return;}
  if(action==='theme'){state.settings.theme=(state.settings.theme||'dark')==='dark'?'light':'dark';save();render();return;}
  if(action==='mic'||action==='camera'){await LocalMedia.toggle(action);return;}
  if(action==='devices'){close();ui.lobbyRole=ui.route==='participant'?'participant':'facilitator';ui.waiting=false;go('lobby');return;}
  if(action==='close-panel'){const panel=ui.panel;ui.panel='';render();document.querySelector(`[data-action="panel-${panel}"]`)?.focus({preventScroll:true});return;}
  if(action==='sound-check'){modal('Sound check',soundCheck());return;}
  if(action==='session-options'){modal('Session options',`<div class="actions">${btn('Camera & microphone','devices','','settings')}${btn('Sound check','sound-check','','volume')}${btn('Captions','captions','','book')}${btn('Demo help','guide','','help')}</div><p>Camera and microphone stay local. Other people and room audio are simulated.</p>`);return;}
  if(action==='speaker-test'){await LocalMedia.testSpeaker();return;}
  if(action==='listen-self'){LocalMedia.listen();return;}
  if(action==='music'){await LocalMedia.toggleMusic();return;}
  if(action.startsWith('lobby-')){ui.lobbyRole=action.slice(6);ui.waiting=false;LocalMedia.pauseMusic();if(['run','participant'].includes(ui.route)){go(ui.lobbyRole==='participant'?'participant':'run');}else if(ui.route!=='lobby'){go('lobby');}else render();return;}
  if(action==='ask-join'){ui.waiting=true;render();await LocalMedia.playMusic();return;}
  if(action==='cancel-wait'){ui.waiting=false;LocalMedia.pauseMusic();render();return;}
  if(action==='join-now'){ui.joined=true;ui.waiting=false;LocalMedia.pauseMusic();LocalMedia.stopListening();state.started=true;save();ui.venue='main';go(ui.lobbyRole==='participant'?'participant':'run');return;}
  if(action==='guide'){modal('Quick guide','<p><strong>Build</strong> the agenda. <strong>Run</strong> the session. <strong>Review</strong> the work.</p><p>In the lobby, turn on your camera and mic, check the level meter, and test your speakers. Participant mode lets you try the waiting room and music.</p><p>Devices work locally. Other people and room audio are simulated. Nothing is recorded or transmitted.</p>');return;}
  if(action==='workspace'||action==='profile'){go('settings');return;}
  if(action==='reset'){confirmAction('Reset the demo?','This removes your changes to this demo on this browser and restores the fictional workshop. Download your demo records first if you want to keep them.','confirm-reset','Reset demo');return;}
  if(action==='confirm-reset'){formDrafts.clear();state=Debrio.seed();save();close();ui.edit=0;ui.person=0;ui.monitor=null;go('home');render();toast('Sample workshop restored.');return;}
  if(action==='new'||action==='details'){modal(action==='new'?'Create a workshop':'Workshop details',`<form id="workshop-form" data-new="${action==='new'}"><label for="workshop-title">Workshop name</label><input id="workshop-title" name="title" value="${action==='new'?'':esc(state.title)}" placeholder="Give your workshop a name" maxlength="100" required><label for="workshop-description">What will people take away?</label><textarea id="workshop-description" name="description" maxlength="500" required>${action==='new'?'':esc(state.description)}</textarea>${action==='new'?'<p class="field-help">This single-workshop demo replaces the current rehearsal. Download any records you want to keep first.</p>':''}<div class="dialog-actions">${btn('Cancel','close')}<button class="btn primary" type="submit">${action==='new'?'Create workshop':'Save details'}</button></div></form>`);return;}
  if(action.startsWith('edit-')){ui.edit=Number(action.slice(5));render();return;}
  if(action==='add-stage'){modal('Add activity',`<div class="template-picker">${Object.entries(Debrio.templates).map(([k,t])=>`<button data-action="template-${k}">${icon(k==='custom'?'plus':'rooms')}<span><strong>${t.name}</strong><small>${t.subtitle} · ${t.steps.length} activities</small></span>${icon('arrow')}</button>`).join('')}</div>`);return;}
  if(action.startsWith('template-')){const kind=action.slice(9);ui.edit=state.agenda.length;state.agenda.push(...Debrio.stages(kind));save();close();go('build');render();toast(`${Debrio.templates[kind].name} added to your agenda.`);return;}
  if(action==='move-up'||action==='move-down'){const from=ui.edit,to=from+(action==='move-up'?-1:1),activeId=current().id;if(to<0||to>=state.agenda.length)return;[state.agenda[from],state.agenda[to]]=[state.agenda[to],state.agenda[from]];state.current=state.agenda.findIndex(a=>a.id===activeId);ui.edit=to;save();render();return;}
  if(action==='remove-stage'){if(ui.edit===state.current&&state.started&&!state.ended){toast('The active activity cannot be removed. Move the session on first.');return;}confirmAction('Remove this activity?',`Remove “${esc(state.agenda[ui.edit].title)}” from the agenda? Submitted work is retained in Review.`,'confirm-remove','Remove activity');return;}
  if(action==='confirm-remove'){if(state.agenda.length<2)return;const activeId=current().id;formDrafts.delete('stage-form:'+state.agenda[ui.edit].id);state.agenda.splice(ui.edit,1);state.current=Math.max(0,state.agenda.findIndex(a=>a.id===activeId));ui.edit=Math.min(ui.edit,state.agenda.length-1);save();close();render();return;}
  if(action==='assignments'){const s=state.agenda[ui.edit];modal('Assignment preview',`<p>${assignmentSummary(s.grouping)}</p><div class="assignment-list">${state.participants.map(p=>{const a=Debrio.assignment(p.id,s.grouping,state.round);return `<div class="person-row">${avatar(p)}<span>${esc(p.name)}<small>${a.room} · ${a.role}</small></span>${badge(p.admitted?'Admitted':'Waiting',p.admitted?'success':'amber')}</div>`;}).join('')}</div>`,true);return;}
  if(action.startsWith('venue-')){ui.venue=action.slice(6);ui.monitor=null;render();return;}
  if(action.startsWith('panel-')){const panel=action.slice(6);ui.panel=ui.panel===panel?'':panel;render();return;}
  if(['captions','gallery'].includes(action)){ui[action]=!ui[action];render();if(action==='captions')toast(`Sample captions ${ui.captions?'on':'off'}. Live transcription is not connected.`);return;}
  if(action==='present'){modal('Present to the room',`<p>The activity presentation is already shared in this demo. In the finished product, this control opens your browser’s screen-sharing picker.</p><div class="inset"><strong>One presenter at a time</strong><p>Sharing a screen would request an explicit handover from the current presenter.</p></div>${btn('Show activity presentation','show-presentation','primary','screen')}`);return;}
  if(action==='show-presentation'){ui.gallery=false;close();render();return;}
  if(action==='hand'){toast(`${ui.route==='participant'?person(ui.person).name:state.settings.name} raised a hand in the demo.`);return;}
  if(action==='timer'){const seconds=Debrio.remaining(state);state.remaining=seconds;if(state.deadline)state.deadline=null;else if(seconds>0){state.deadline=Date.now()+seconds*1000;state.started=true;}else{toast('Time is up. Add a minute or start the next activity.');return;}save();render();return;}
  if(action==='add-minute'){state.remaining=Debrio.remaining(state)+60;if(state.deadline)state.deadline=Date.now()+state.remaining*1000;save();render();return;}
  if(action==='next'||action.startsWith('jump-')){transition(action==='next'?state.current+1:Number(action.slice(5)));return;}
  if(action.startsWith('advance-')){if(!$('#transition-confirm').checked){toast('Confirm the group is ready before starting.');$('#transition-confirm').focus();return;}state.current=Number(action.slice(8));state.started=true;state.remaining=current().minutes*60;state.deadline=Date.now()+state.remaining*1000;ui.monitor=null;ui.venue=['main','individual'].includes(current().grouping)?'main':'breakouts';save();close();render();toast('Activity started. Instructions and assignments updated.');return;}
  if(action==='rotate'){confirmAction('Rotate practice roles?','Practitioners, counterparts, and observers will rotate within their assigned groups. Everyone keeps their attempts and feedback.','confirm-rotate','Rotate roles');return;}
  if(action==='confirm-rotate'){state.round++;save();close();render();toast('Roles rotated. Check participant preview to see the new assignment.');return;}
  if(action==='end'){confirmAction('Bring this session to a close?','The timer stops and submitted work remains available in Review. Unsaved submissions are not manufactured; local drafts are retained.','confirm-end','End session');return;}
  if(action==='confirm-end'){state.remaining=Debrio.remaining(state);state.deadline=null;state.ended=true;state.poll.open=false;ui.monitor=null;save();close();go('review');return;}
  if(action.startsWith('listen-')||action.startsWith('speak-')||action.startsWith('join-')){const [mode,index]=action.split('-');ui.monitor={room:roomNames()[Number(index)],mode:{listen:'Listening',speak:'Speaking',join:'Joined'}[mode]};render();toast(`${ui.monitor.mode} in ${ui.monitor.room}. Named presence is visible; audio is simulated.`);return;}
  if(action==='stop-monitor'){ui.monitor=null;render();return;}
  if(action==='admit-all'||action.startsWith('admit-')){state.participants.forEach(p=>{if(action==='admit-all'||p.id===Number(action.slice(6)))p.admitted=true;});save();render();toast('Admitted to the demo session.');return;}
  if(action==='help'){modal('Ask your facilitator',`<form id="help-form"><p>Your request will appear beside your group in the facilitator console.</p><label for="help-text">What would help? (optional)</label><textarea id="help-text" name="text" rows="3" maxlength="500"></textarea><button class="btn primary" type="submit">Request help in demo</button></form>`);return;}
  if(action.startsWith('resolve-')){const h=state.help.find(h=>h.id===action.slice(8));h.resolved=true;save();render();toast('Help request marked resolved.');return;}
  if(action==='announce'){modal('Announcement',`<form id="announcement-form"><label for="announcement-target">Send to</label><select name="target" id="announcement-target"><option value="all">Everyone in this session</option>${roomNames().map(r=>`<option>${esc(r)}</option>`).join('')}</select><label for="announcement-text">Your message</label><textarea id="announcement-text" name="text" maxlength="1000" rows="4" placeholder="A quick note for everyone…" required></textarea><p class="field-help">Written announcement only in this demo. No email or live audio is sent.</p><button class="btn primary" type="submit">${icon('volume')} Announce in demo</button></form>`);return;}
  if(action.startsWith('resource-')){const r=state.resources.find(r=>r.id===action.slice(9));if(ui.route==='participant'&&!Debrio.visibleResources(state,ui.person).includes(r))return;modal(esc(r.title),`${badge(esc(r.type))} ${badge('Audience: '+esc(r.audience))}<div class="resource-body">${esc(r.body)}</div>${btn('Download text',`download-resource-${r.id}`,'','download')}`);return;}
  if(action.startsWith('download-resource-')){const r=state.resources.find(r=>r.id===action.slice(18));download(r.title+'.txt',r.body,'text/plain');return;}
  if(action.startsWith('release-')){const r=state.resources.find(r=>r.id===action.slice(8));r.released=!r.released;save();render();toast(r.released?'Resource released to its assigned audience.':'Resource removed from participant resources.');return;}
  if(action==='add-resource'){modal('Add a workshop resource',`<form id="resource-form"><label for="resource-title">Resource title</label><input id="resource-title" name="title" maxlength="100" required><label for="resource-audience">Audience</label><select id="resource-audience" name="audience"><option value="all">Everyone</option><option value="practitioner">Practitioners</option><option value="counterpart">Counterparts</option><option value="observer">Observers</option></select><label for="resource-body">Resource content</label><textarea id="resource-body" name="body" maxlength="10000" rows="6" required></textarea><p class="field-help">Text resources are supported locally. New resources wait for manual release.</p><button type="submit" class="btn primary">Add resource</button></form>`);return;}
  if(action.startsWith('vote-')){if(!state.poll.open||state.ended){toast('Voting is closed.');return;}state.poll.votes[ui.person]=Number(action.slice(5));save();render();toast('Vote saved. You can change it while voting is open.');return;}
  if(action==='poll-toggle'||action==='poll-reveal'){const prop=action==='poll-toggle'?'open':'revealed';state.poll[prop]=!state.poll[prop];save();render();return;}
  if(action.startsWith('consent-')){const a=state.attempts.find(a=>a.id===action.slice(8));if(a.author!==ui.person)return;a.approved=!a.approved;save();render();toast(a.approved?'This exact version is approved for the workshop debrief.':'Sharing withdrawn. This item is no longer in the debrief presentation.');return;}
  if(action.startsWith('filter-')){ui.reviewFilter=action.slice(7);render();return;}
  if(action.startsWith('pin-')){const a=state.attempts.find(a=>a.id===action.slice(4));a.pinned=!a.pinned;save();render();toast(a.pinned?(a.approved?'Added to your debrief.':'Pinned for planning. Author approval is still needed before presentation.'):'Removed from your debrief.');return;}
  if(action.startsWith('feedback-')){const a=state.attempts.find(a=>a.id===action.slice(9));modal('Feedback',`<form id="feedback-form" data-id="${a.id}"><p class="quote">${esc(a.text)}</p><fieldset><legend>Observed criteria</legend>${['Uses a specific observation','Asks an open question','Agrees a concrete next step'].map((c,i)=>`<label class="check-label"><input type="checkbox" name="c${i}" ${a.criteria?.[i]?'checked':''}>${c}</label>`).join('')}</fieldset><label for="feedback-text">Written feedback</label><textarea id="feedback-text" name="feedback" rows="4" required maxlength="2000">${esc(a.feedback)}</textarea><button type="submit" class="btn primary">Save feedback</button></form>`);return;}
  if(action.startsWith('compare-')){const a=state.attempts.find(a=>a.id===action.slice(8)),prior=state.attempts.find(p=>p.id===a.previous);modal('Compare attempts',`<div class="comparison"><div><div class="eyebrow">EARLIER · VERSION ${prior.version}</div><p>${esc(prior.text)}</p></div><div><div class="eyebrow">REVISION · VERSION ${a.version}</div><p>${esc(a.text)}</p></div></div><p class="field-help">Both versions are preserved. A change in response is evidence to discuss, not an automatic learning score.</p>`,true);return;}
  if(action==='debrief'){const items=Debrio.curated(state);modal('Debrief',`<div class="debrief-presentation"><div class="eyebrow">${esc(state.title)} · WORKSHOP DEBRIEF</div>${items.map((a,i)=>`<article><span class="eyebrow">MOMENT ${i+1} · ${a.group?esc(a.group)+' group':esc(person(a.author).name)} · V${a.version}</span><blockquote>${esc(a.text)}</blockquote></article>`).join('')||empty('No approved moments yet','Pin work in Review and approve the exact version from its author’s participant preview.')}<h3>What changed in your thinking, and what helped it change?</h3></div><div class="dialog-actions">${btn('Download approved debrief','export-debrief','','download')}${btn('Back to review','goto-review','primary')}</div>`,true);return;}
  if(action==='export'){modal('Export workshop records',`<p>Facilitator-only demo exports include fictional participant work, feedback, and version links. Use the approved debrief export when sharing workshop material.</p><div class="dialog-actions">${btn('Responses CSV','export-csv','','download')}${btn('Full demo JSON','export-json','primary','download')}</div>`);return;}
  if(action==='export-json'){download('debrio-demo-records.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');return;}
  if(action==='export-csv'){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Author','Activity','Version','Previous attempt','Response','Feedback','Workshop sharing'],...state.attempts.map(a=>[a.group||person(a.author).name,a.title,a.version,a.previous,a.text,a.feedback,a.approved?'Approved':'Not approved'])];download('debrio-responses.csv','\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');return;}
  if(action==='export-debrief'){download('debrio-approved-debrief.txt',`${state.title}\nWorkshop audience only · Synthetic demo data\n\n`+Debrio.curated(state).map(a=>`${a.group||person(a.author).name} · Version ${a.version}\n${a.text}`).join('\n\n'),'text/plain');return;}
});
document.addEventListener('submit',event=>{
  event.preventDefault();const f=event.target,d=new FormData(f);if(!f.reportValidity())return;
  if(f.id==='stage-form'){const title=d.get('title').trim(),instructions=d.get('instructions').trim();if(!title||!instructions){toast('Please add an activity name and instructions.');return;}const s=state.agenda[ui.edit];s.title=title;s.minutes=Number(d.get('minutes'));s.grouping=d.get('grouping');s.instructions=instructions;formDrafts.delete(draftKey(f));save();render();toast('Activity saved.');}
  if(f.id==='workshop-form'){const title=d.get('title').trim(),description=d.get('description').trim();if(!title||!description){toast('Add a name and description.');return;}if(f.dataset.new==='true'){formDrafts.clear();state=Debrio.seed();state.agenda=Debrio.stages('custom');state.attempts=[];state.help=[];state.messages=[];state.current=0;state.remaining=300;ui.edit=0;}state.title=title;state.description=description;save();close();go('build');render();}
  if(f.id==='response-form'){try{Debrio.submit(state,ui.person,d.get('text'));delete state.drafts[ui.person+':'+current().id];save();render();toast('Response submitted. This version is preserved in Review.');}catch(e){toast(e.message);}}
  if(f.id==='group-form'){try{Debrio.submitGroup(state,ui.person,d.get('text'));save();render();toast('Group snapshot submitted with all contributors preserved.');}catch(e){toast(e.message);}}
  if(f.id==='message-form'||f.id==='announcement-form'){const text=d.get('text').trim();if(!text)return;const participant=ui.route==='participant';state.messages.push({id:'m-'+Date.now(),author:participant?person(ui.person).name:state.settings.name,target:f.id==='announcement-form'?d.get('target'):participant?Debrio.assignment(ui.person,current().grouping,state.round).room:'all',text,time:new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',timeZone:'America/Indianapolis'})});ui.panel='messages';ui.monitor=null;formDrafts.delete(draftKey(f));save();close();render();toast('Message saved in the demo.');}
  if(f.id==='help-form'){const a=Debrio.assignment(ui.person,current().grouping,state.round);state.help.push({id:'h-'+Date.now(),author:ui.person,room:a.room,text:d.get('text').trim()||'We would appreciate a hand with this activity.',resolved:false});save();close();toast('Help requested. Switch to facilitator Messages to see it.');}
  if(f.id==='resource-form'){const title=d.get('title').trim(),body=d.get('body').trim();if(!title||!body)return;state.resources.push({id:'r-'+Date.now(),title,body,audience:d.get('audience'),type:'Text resource',released:false});save();close();render();toast('Resource added. Release it when your group is ready.');}
  if(f.id==='feedback-form'){const a=state.attempts.find(a=>a.id===f.dataset.id);a.feedback=d.get('feedback').trim();if(!a.feedback)return;a.criteria=[0,1,2].map(i=>d.has('c'+i));save();close();render();toast('Feedback saved for the author to use in their next attempt.');}
  if(f.id==='settings-form'){const name=d.get('name').trim(),workspace=d.get('workspace').trim();if(!name||!workspace)return;state.settings.name=name;state.settings.workspace=workspace;formDrafts.delete(draftKey(f));save();render();toast('Preferences saved.');}
});
document.addEventListener('input',event=>{const form=event.target.closest('#app form[data-draft-key]');if(form){formDrafts.set(draftKey(form),[...new FormData(form)]);if(form.id==='stage-form')$('#activity-save-status').textContent='Unsaved edits';}if(event.target.id==='music-volume'){LocalMedia.setVolume(event.target.value);return;}if(event.target.id==='group-response'){state.drafts[event.target.dataset.draft]=event.target.value;save();}if(event.target.id==='response'){state.drafts[ui.person+':'+current().id]=event.target.value;save();$('#draft-status').textContent=storageFailed?'In memory only · browser storage unavailable':'Draft saved on this browser · private to you and facilitator';}if(event.target.id==='evidence-search'){const input=event.target;const pos=input.selectionStart;ui.search=input.value;render();$('#evidence-search').focus();$('#evidence-search').setSelectionRange?.(pos,pos);}});
document.addEventListener('change',async event=>{if(event.target.dataset.device){const kind=event.target.dataset.device;if(kind==='speaker'){await LocalMedia.setOutput(event.target.value);return;}LocalMedia.state[kind+'Id']=event.target.value;if(LocalMedia.state[kind])await LocalMedia.start(kind,event.target.value);return;}if(event.target.id==='preview-person'){ui.person=Number(event.target.value);render();}});
$('.skip').addEventListener('click',event=>{event.preventDefault();$('#main').focus();});
function download(name,body,type){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download prepared.');}
window.addEventListener('hashchange',()=>{LocalMedia.stopListening();ui.route=location.hash.slice(1)||'lobby';render();$('#main')?.focus({preventScroll:true});window.scrollTo(0,0);});
$('#dialog').addEventListener('close',()=>LocalMedia.stopListening());
window.addEventListener('debrio-media',()=>{const action=$('#dialog').contains(document.activeElement)?document.activeElement.dataset.action:null;render();const content=$('#sound-check-content');if(content){content.outerHTML=soundCheck();if(action)[...$('#dialog').querySelectorAll('[data-action]')].find(el=>el.dataset.action===action)?.focus();}});
// shortcut: one browser owns a rehearsal; use server-authoritative state before multi-user delivery.
setInterval(()=>{if(!state.deadline)return;const seconds=Debrio.remaining(state);const clock=$('#timer');if(clock)clock.textContent=formatTime(seconds);if(seconds===0){state.deadline=null;state.remaining=0;save();if(!$('#dialog').open)render();toast('Time is up. Work stays open until you choose the next activity.');}},1000);
render();
